  /**
   * @method
   * @name blockchaincom#fetchMarkets
   * @description retrieves data on all markets for blockchaincom
   * @see https://api.blockchain.com/v3/#getsymbols
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} an array of objects representing market data
   */
  std::shared_future<ccxt::any>
  fetchMarkets(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 //
                 //     "USDC-GBP": {
                 //         "base_currency": "USDC",
                 //         "base_currency_scale": 6,
                 //         "counter_currency": "GBP",
                 //         "counter_currency_scale": 2,
                 //         "min_price_increment": 10000,
                 //         "min_price_increment_scale": 8,
                 //         "min_order_size": 500000000,
                 //         "min_order_size_scale": 8,
                 //         "max_order_size": 0,
                 //         "max_order_size_scale": 8,
                 //         "lot_size": 10000,
                 //         "lot_size_scale": 8,
                 //         "status": "open",
                 //         "id": 68,
                 //         "auction_price": 0,
                 //         "auction_size": 0,
                 //         "auction_time": "",
                 //         "imbalance": 0
                 //     }
                 //
                 ccxt::any markets = awaitValue(this->publicGetSymbols(params));
                 ccxt::any marketIds = getObjectKeys(markets);
                 ccxt::any result = ccxt::list{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(marketIds));
                      postFixIncrement(i)) {
                   ccxt::any marketId = ::getValue(marketIds, i);
                   ccxt::any market = this->safeValue(markets, marketId);
                   ccxt::any baseId =
                       this->safeString(market, std::string("base_currency"));
                   ccxt::any quoteId = this->safeString(
                       market, std::string("counter_currency"));
                   ccxt::any base = this->safeCurrencyCode(baseId);
                   ccxt::any quote = this->safeCurrencyCode(quoteId);
                   ccxt::any numericId =
                       this->safeNumber(market, std::string("id"));
                   ccxt::any active = ccxt::any{};
                   ccxt::any marketState =
                       this->safeString(market, std::string("status"));
                   if (isTrue(isEqual(marketState, std::string("open")))) {
                     active = true;
                   } else {
                     active = false;
                   }
                   // price precision
                   ccxt::any minPriceIncrementString = this->safeString(
                       market, std::string("min_price_increment"));
                   ccxt::any minPriceIncrementScaleString = this->safeString(
                       market, std::string("min_price_increment_scale"));
                   ccxt::any minPriceScalePrecisionString =
                       this->parsePrecision(minPriceIncrementScaleString);
                   ccxt::any pricePrecisionString = ccxt::Precise::stringMul(
                       minPriceIncrementString, minPriceScalePrecisionString);
                   // amount precision
                   ccxt::any lotSizeString =
                       this->safeString(market, std::string("lot_size"));
                   ccxt::any lotSizeScaleString =
                       this->safeString(market, std::string("lot_size_scale"));
                   ccxt::any lotSizeScalePrecisionString =
                       this->parsePrecision(lotSizeScaleString);
                   ccxt::any amountPrecisionString = ccxt::Precise::stringMul(
                       lotSizeString, lotSizeScalePrecisionString);
                   // minimum order size
                   ccxt::any minOrderSizeString =
                       this->safeString(market, std::string("min_order_size"));
                   ccxt::any minOrderSizeScaleString = this->safeString(
                       market, std::string("min_order_size_scale"));
                   ccxt::any minOrderSizeScalePrecisionString =
                       this->parsePrecision(minOrderSizeScaleString);
                   ccxt::any minOrderSizePreciseString =
                       ccxt::Precise::stringMul(
                           minOrderSizeString,
                           minOrderSizeScalePrecisionString);
                   ccxt::any minOrderSize =
                       this->parseNumber(minOrderSizePreciseString);
                   // maximum order size
                   ccxt::any maxOrderSize = ccxt::any{};
                   ccxt::any maxOrderSizeRaw =
                       this->safeString(market, std::string("max_order_size"));
                   if (isTrue(!isEqual(maxOrderSizeRaw, std::string("0")))) {
                     ccxt::any maxOrderSizeScaleString = this->safeString(
                         market, std::string("max_order_size_scale"));
                     ccxt::any maxOrderSizeScalePrecisionString =
                         this->parsePrecision(maxOrderSizeScaleString);
                     ccxt::any maxOrderSizeValueString =
                         ccxt::Precise::stringMul(
                             maxOrderSizeRaw, maxOrderSizeScalePrecisionString);
                     maxOrderSize = this->parseNumber(maxOrderSizeValueString);
                   }
                   arrayPush(
                       result,
                       ccxt::dict{
                           {std::string("info"), market},
                           {std::string("id"), marketId},
                           {std::string("numericId"), numericId},
                           {std::string("symbol"),
                            add(add(base, std::string("/")), quote)},
                           {std::string("base"), base},
                           {std::string("quote"), quote},
                           {std::string("settle"), ccxt::any{}},
                           {std::string("baseId"), baseId},
                           {std::string("quoteId"), quoteId},
                           {std::string("settleId"), ccxt::any{}},
                           {std::string("type"), std::string("spot")},
                           {std::string("spot"), true},
                           {std::string("margin"), false},
                           {std::string("swap"), false},
                           {std::string("future"), false},
                           {std::string("option"), false},
                           {std::string("active"), active},
                           {std::string("contract"), false},
                           {std::string("linear"), ccxt::any{}},
                           {std::string("inverse"), ccxt::any{}},
                           {std::string("contractSize"), ccxt::any{}},
                           {std::string("expiry"), ccxt::any{}},
                           {std::string("expiryDatetime"), ccxt::any{}},
                           {std::string("strike"), ccxt::any{}},
                           {std::string("optionType"), ccxt::any{}},
                           {std::string("precision"),
                            ccxt::dict{
                                {std::string("amount"),
                                 this->parseNumber(amountPrecisionString)},
                                {std::string("price"),
                                 this->parseNumber(pricePrecisionString)},
                            }},
                           {std::string("limits"),
                            ccxt::dict{
                                {std::string("leverage"),
                                 ccxt::dict{
                                     {std::string("min"), ccxt::any{}},
                                     {std::string("max"), ccxt::any{}},
                                 }},
                                {std::string("amount"),
                                 ccxt::dict{
                                     {std::string("min"), minOrderSize},
                                     {std::string("max"), maxOrderSize},
                                 }},
                                {std::string("price"),
                                 ccxt::dict{
                                     {std::string("min"), ccxt::any{}},
                                     {std::string("max"), ccxt::any{}},
                                 }},
                                {std::string("cost"),
                                 ccxt::dict{
                                     {std::string("min"), ccxt::any{}},
                                     {std::string("max"), ccxt::any{}},
                                 }},
                            }},
                           {std::string("created"), ccxt::any{}},
                       });
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name blockchaincom#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see https://api.blockchain.com/v3/#getl3orderbook
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        return awaitValue(
                            this->fetchL3OrderBook(symbol, limit, params));
                      })
        .share();
  }

  /**
   * @method
   * @name blockchaincom#fetchL3OrderBook
   * @description fetches level 3 information on open orders with bid (buy) and
   * ask (sell) prices, volumes and other data
   * @see https://api.blockchain.com/v3/#getl3orderbook
   * @param {string} symbol unified market symbol
   * @param {int} [limit] max number of orders to return, default is undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchL3OrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                   ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = this->market(symbol);
                        ccxt::any request = ccxt::dict{
                            {std::string("symbol"),
                             ::getValue(market, std::string("id"))},
                        };
                        if (isTrue(!isEqual(limit, ccxt::any{}))) {
                          ::setValue(request, std::string("depth"), limit);
                        }
                        ccxt::any response = awaitValue(this->publicGetL3Symbol(
                            this->extend(request, params)));
                        return this->parseOrderBook(
                            response, ::getValue(market, std::string("symbol")),
                            ccxt::any{}, std::string("bids"),
                            std::string("asks"), std::string("px"),
                            std::string("qty"));
                      })
        .share();
  }

