  virtual ccxt::any parseOrderState(ccxt::any state) {
    ccxt::any states = ccxt::dict{
        {std::string("OPEN"), std::string("open")},
        {std::string("REJECTED"), std::string("rejected")},
        {std::string("FILLED"), std::string("closed")},
        {std::string("CANCELED"), std::string("canceled")},
        {std::string("PART_FILLED"), std::string("open")},
        {std::string("EXPIRED"), std::string("expired")},
    };
    return this->safeString(states, state, state);
  }

  ccxt::any parseOrder(ccxt::any order,
                       ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "clOrdId": "00001",
    //         "ordType": "MARKET",
    //         "ordStatus": "FILLED",
    //         "side": "BUY",
    //         "symbol": "USDC-USDT",
    //         "exOrdId": "281775861306290",
    //         "price": null,
    //         "text": "Fill",
    //         "lastShares": "30.0",
    //         "lastPx": "0.9999",
    //         "leavesQty": "0.0",
    //         "cumQty": "30.0",
    //         "avgPx": "0.9999",
    //         "timestamp": "1633940339619"
    //     }
    //
    ccxt::any clientOrderId = this->safeString(order, std::string("clOrdId"));
    ccxt::any type = this->safeStringLower(order, std::string("ordType"));
    ccxt::any statusId = this->safeString(order, std::string("ordStatus"));
    ccxt::any state = this->parseOrderState(statusId);
    ccxt::any side = this->safeStringLower(order, std::string("side"));
    ccxt::any marketId = this->safeString(order, std::string("symbol"));
    ccxt::any symbol = this->safeSymbol(marketId, market, std::string("-"));
    ccxt::any exchangeOrderId = this->safeString(order, std::string("exOrdId"));
    ccxt::any price =
        (isTrue((!isEqual(type, std::string("market"))))
             ? ccxt::any(this->safeString(order, std::string("price")))
             : ccxt::any(ccxt::any{}));
    ccxt::any average = this->safeNumber(order, std::string("avgPx"));
    ccxt::any timestamp = this->safeInteger(order, std::string("timestamp"));
    ccxt::any datetime = this->iso8601(timestamp);
    ccxt::any filled = this->safeString(order, std::string("cumQty"));
    ccxt::any remaining = this->safeString(order, std::string("leavesQty"));
    ccxt::any result = this->safeOrder(ccxt::dict{
        {std::string("id"), exchangeOrderId},
        {std::string("clientOrderId"), clientOrderId},
        {std::string("datetime"), datetime},
        {std::string("timestamp"), timestamp},
        {std::string("lastTradeTimestamp"), ccxt::any{}},
        {std::string("status"), state},
        {std::string("symbol"), symbol},
        {std::string("type"), type},
        {std::string("timeInForce"), ccxt::any{}},
        {std::string("side"), side},
        {std::string("price"), price},
        {std::string("average"), average},
        {std::string("amount"), ccxt::any{}},
        {std::string("filled"), filled},
        {std::string("remaining"), remaining},
        {std::string("cost"), ccxt::any{}},
        {std::string("trades"), ccxt::list{}},
        {std::string("fees"), ccxt::list{}},
        {std::string("info"), order},
    });
    return result;
  }

  /**
   * @method
   * @name blockchaincom#createOrder
   * @description create a trade order
   * @see https://api.blockchain.com/v3/#createorder
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
              ccxt::any amount, ccxt::any price = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any orderType =
                     this->safeString(params, std::string("ordType"), type);
                 ccxt::any uppercaseOrderType = toUpperCase(orderType);
                 ccxt::any clientOrderId =
                     this->safeString2(params, std::string("clientOrderId"),
                                       std::string("clOrdId"), this->uuid16());
                 params =
                     this->omit(params, ccxt::list{std::string("ordType"),
                                                   std::string("clientOrderId"),
                                                   std::string("clOrdId")});
                 if (isTrue(isEqual(side, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " createOrder() requires a side argument"))));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("ordType"), uppercaseOrderType},
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("side"), toUpperCase(side)},
                     {std::string("orderQty"),
                      this->amountToPrecision(symbol, amount)},
                     {std::string("clOrdId"), clientOrderId},
                 };
                 ccxt::any triggerPrice = this->safeValueN(
                     params, ccxt::list{std::string("triggerPrice"),
                                        std::string("stopPx"),
                                        std::string("stopPrice")});
                 params =
                     this->omit(params, ccxt::list{std::string("triggerPrice"),
                                                   std::string("stopPx"),
                                                   std::string("stopPrice")});
                 if (isTrue(isTrue(isEqual(uppercaseOrderType,
                                           std::string("STOP"))) ||
                            isTrue(isEqual(uppercaseOrderType,
                                           std::string("STOPLIMIT"))))) {
                   if (isTrue(isEqual(triggerPrice, ccxt::any{}))) {
                     throw ArgumentsRequired(toString(add(
                         add(add(this->id,
                                 std::string(" createOrder() requires a stopPx "
                                             "or triggerPrice param for a ")),
                             uppercaseOrderType),
                         std::string(" order"))));
                   }
                 }
                 if (isTrue(!isEqual(triggerPrice, ccxt::any{}))) {
                   if (isTrue(isEqual(uppercaseOrderType,
                                      std::string("MARKET")))) {
                     ::setValue(request, std::string("ordType"),
                                std::string("STOP"));
                   } else if (isTrue(isEqual(uppercaseOrderType,
                                             std::string("LIMIT")))) {
                     ::setValue(request, std::string("ordType"),
                                std::string("STOPLIMIT"));
                   }
                 }
                 ccxt::any priceRequired = false;
                 ccxt::any stopPriceRequired = false;
                 if (isTrue(isTrue(isEqual(
                                ::getValue(request, std::string("ordType")),
                                std::string("LIMIT"))) ||
                            isTrue(isEqual(
                                ::getValue(request, std::string("ordType")),
                                std::string("STOPLIMIT"))))) {
                   priceRequired = true;
                 }
                 if (isTrue(isTrue(isEqual(
                                ::getValue(request, std::string("ordType")),
                                std::string("STOP"))) ||
                            isTrue(isEqual(
                                ::getValue(request, std::string("ordType")),
                                std::string("STOPLIMIT"))))) {
                   stopPriceRequired = true;
                 }
                 if (isTrue(priceRequired)) {
                   ::setValue(request, std::string("price"),
                              this->priceToPrecision(symbol, price));
                 }
                 if (isTrue(stopPriceRequired)) {
                   ::setValue(request, std::string("stopPx"),
                              this->priceToPrecision(symbol, triggerPrice));
                 }
                 ccxt::any response = awaitValue(
                     this->privatePostOrders(this->extend(request, params)));
                 return this->parseOrder(response, market);
               })
        .share();
  }

  /**
   * @method
   * @name blockchaincom#cancelOrder
   * @description cancels an open order
   * @see https://api.blockchain.com/v3/#deleteorder
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any request = ccxt::dict{
                            {std::string("orderId"), id},
                        };
                        ccxt::any response =
                            awaitValue(this->privateDeleteOrdersOrderId(
                                this->extend(request, params)));
                        return this->safeOrder(ccxt::dict{
                            {std::string("id"), id},
                            {std::string("info"), response},
                        });
                      })
        .share();
  }

  /**
   * @method
   * @name blockchaincom#cancelAllOrders
   * @description cancel all open orders
   * @see https://api.blockchain.com/v3/#deleteallorders
   * @param {string} [symbol] unified market symbol of the market to cancel
   * orders in, all markets are used if undefined, default is undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelAllOrders(ccxt::any symbol = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        // cancels all open orders if no symbol specified
                        // cancels all open orders of specified symbol, if
                        // symbol is specified
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any request = ccxt::dict{};
                        if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                          ccxt::any marketId = this->marketId(symbol);
                          ::setValue(request, std::string("symbol"), marketId);
                        }
                        ccxt::any response =
                            awaitValue(this->privateDeleteOrders(
                                this->extend(request, params)));
                        //
                        // {}
                        //
                        return ccxt::list{this->safeOrder(ccxt::dict{
                            {std::string("info"), response},
                        })};
                      })
        .share();
  }

  /**
   * @method
   * @name blockchaincom#fetchTradingFees
   * @description fetch the trading fees for multiple markets
   * @see https://api.blockchain.com/v3/#getfees
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [fee structures]{@link
   * https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
   */
  std::shared_future<ccxt::any>
  fetchTradingFees(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any response = awaitValue(this->privateGetFees(params));
                 //
                 //     {
                 //         "makerRate": "0.002",
                 //         "takerRate": "0.004",
                 //         "volumeInUSD": "0.0"
                 //     }
                 //
                 ccxt::any makerFee =
                     this->safeNumber(response, std::string("makerRate"));
                 ccxt::any takerFee =
                     this->safeNumber(response, std::string("takerRate"));
                 ccxt::any result = ccxt::dict{};
                 ccxt::any symbols = this->symbols;
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(symbols));
                      postFixIncrement(i)) {
                   ccxt::any symbol = ::getValue(symbols, i);
                   ::setValue(result, symbol,
                              ccxt::dict{
                                  {std::string("info"), response},
                                  {std::string("symbol"), symbol},
                                  {std::string("maker"), makerFee},
                                  {std::string("taker"), takerFee},
                              });
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name blockchaincom#fetchCanceledOrders
   * @description fetches information on multiple canceled orders made by the
   * user
   * @see https://api.blockchain.com/v3/#getorders
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] timestamp in ms of the earliest order, default is
   * undefined
   * @param {int} [limit] max number of orders to return, default is undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any> fetchCanceledOrders(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any state = std::string("CANCELED");
                        return awaitValue(this->fetchOrdersByState(
                            state, symbol, since, limit, params));
                      })
        .share();
  }

