  virtual std::shared_future<ccxt::any>
  fetchOrdersByState(ccxt::any state, ccxt::any symbol = ccxt::any{},
                     ccxt::any since = ccxt::any{},
                     ccxt::any limit = ccxt::any{},
                     ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("status"), state},
                     {std::string("limit"), 100},
                 };
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 ccxt::any response = awaitValue(
                     this->privateGetOrders(this->extend(request, params)));
                 return this->parseOrders(response, market, since, limit);
               })
        .share();
  }

  ccxt::any parseTrade(ccxt::any trade,
                       ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "exOrdId":281685751028507,
    //         "tradeId":281685434947633,
    //         "execId":8847494003,
    //         "side":"BUY",
    //         "symbol":"AAVE-USDT",
    //         "price":405.34,
    //         "qty":0.1,
    //         "fee":0.162136,
    //         "timestamp":1634559249687
    //     }
    //
    ccxt::any orderId = this->safeString(trade, std::string("exOrdId"));
    ccxt::any tradeId = this->safeString(trade, std::string("tradeId"));
    ccxt::any side = this->safeStringLower(trade, std::string("side"));
    ccxt::any marketId = this->safeString(trade, std::string("symbol"));
    ccxt::any priceString = this->safeString(trade, std::string("price"));
    ccxt::any amountString = this->safeString(trade, std::string("qty"));
    ccxt::any timestamp = this->safeInteger(trade, std::string("timestamp"));
    ccxt::any datetime = this->iso8601(timestamp);
    market = this->safeMarket(marketId, market, std::string("-"));
    ccxt::any symbol = ::getValue(market, std::string("symbol"));
    ccxt::any fee = ccxt::any{};
    ccxt::any feeCostString = this->safeString(trade, std::string("fee"));
    if (isTrue(!isEqual(feeCostString, ccxt::any{}))) {
      ccxt::any feeCurrency = ::getValue(market, std::string("quote"));
      fee = ccxt::dict{
          {std::string("cost"), feeCostString},
          {std::string("currency"), feeCurrency},
      };
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("id"), tradeId},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), datetime},
            {std::string("symbol"), symbol},
            {std::string("order"), orderId},
            {std::string("type"), ccxt::any{}},
            {std::string("side"), side},
            {std::string("takerOrMaker"), ccxt::any{}},
            {std::string("price"), priceString},
            {std::string("amount"), amountString},
            {std::string("cost"), ccxt::any{}},
            {std::string("fee"), fee},
            {std::string("info"), trade},
        },
        market);
  }

