  /**
   * @method
   * @name blockchaincom#fetchDepositAddress
   * @description fetch the deposit address for a currency associated with this
   * account
   * @see https://api.blockchain.com/v3/#getdepositaddress
   * @param {string} code unified currency code
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [address structure]{@link
   * https://docs.ccxt.com/?id=address-structure}
   */
  std::shared_future<ccxt::any>
  fetchDepositAddress(ccxt::any code,
                      ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any currency = this->currency(code);
                        ccxt::any request = ccxt::dict{
                            {std::string("currency"),
                             ::getValue(currency, std::string("id"))},
                        };
                        ccxt::any response =
                            awaitValue(this->privatePostDepositsCurrency(
                                this->extend(request, params)));
                        ccxt::any rawAddress =
                            this->safeString(response, std::string("address"));
                        ccxt::any tag = ccxt::any{};
                        ccxt::any address = ccxt::any{};
                        if (isTrue(!isEqual(rawAddress, ccxt::any{}))) {
                          ccxt::any addressParts =
                              split(rawAddress, std::string(";"));
                          // if a tag or memo is used it is separated by a colon
                          // in the 'address' value
                          tag = this->safeString(addressParts, 0);
                          address = this->safeString(addressParts, 1);
                        }
                        return ccxt::dict{
                            {std::string("info"), response},
                            {std::string("currency"),
                             ::getValue(currency, std::string("code"))},
                            {std::string("network"), ccxt::any{}},
                            {std::string("address"), address},
                            {std::string("tag"), tag},
                        };
                      })
        .share();
  }

  virtual ccxt::any parseTransactionState(ccxt::any state) {
    ccxt::any states = ccxt::dict{
        {std::string("COMPLETED"), std::string("ok")},
        {std::string("REJECTED"), std::string("failed")},
        {std::string("PENDING"), std::string("pending")},
        {std::string("FAILED"), std::string("failed")},
        {std::string("REFUNDED"), std::string("refunded")},
    };
    return this->safeString(states, state, state);
  }

  ccxt::any parseTransaction(ccxt::any transaction,
                             ccxt::any currency = ccxt::any{},
                             ccxt::any p2 = ccxt::any{},
                             ccxt::any p3 = ccxt::any{}) override {
    //
    // deposit
    //
    //     {
    //         "depositId":"748e9180-be0d-4a80-e175-0156150efc95",
    //         "amount":0.009,
    //         "currency":"ETH",
    //         "address":"0xEC6B5929D454C8D9546d4221ace969E1810Fa92c",
    //         "state":"COMPLETED",
    //         "txHash":"582114562140e51a80b481c2dfebaf62b4ab9769b8ff54820bb67e34d4a3ab0c",
    //         "timestamp":1633697196241
    //     }
    //
    // withdrawal
    //
    //     {
    //         "amount":30.0,
    //         "currency":"USDT",
    //         "beneficiary":"cab00d11-6e7f-46b7-b453-2e8ef6f101fa", //
    //         blockchain specific id
    //         "withdrawalId":"99df5ef7-eab6-4033-be49-312930fbd1ea",
    //         "fee":34.005078,
    //         "state":"COMPLETED",
    //         "timestamp":1634218452549
    //     }
    //
    ccxt::any type = ccxt::any{};
    ccxt::any id = ccxt::any{};
    ccxt::any amount = this->safeNumber(transaction, std::string("amount"));
    ccxt::any timestamp =
        this->safeInteger(transaction, std::string("timestamp"));
    ccxt::any currencyId =
        this->safeString(transaction, std::string("currency"));
    ccxt::any code = this->safeCurrencyCode(currencyId, currency);
    ccxt::any state = this->safeString(transaction, std::string("state"));
    if (isTrue(inOp(transaction, std::string("depositId")))) {
      type = std::string("deposit");
      id = this->safeString(transaction, std::string("depositId"));
    } else if (isTrue(inOp(transaction, std::string("withdrawalId")))) {
      type = std::string("withdrawal");
      id = this->safeString(transaction, std::string("withdrawalId"));
    }
    ccxt::any feeCost =
        (isTrue((isEqual(type, std::string("withdrawal"))))
             ? ccxt::any(this->safeNumber(transaction, std::string("fee")))
             : ccxt::any(ccxt::any{}));
    ccxt::any fee = ccxt::any{};
    if (isTrue(!isEqual(feeCost, ccxt::any{}))) {
      fee = ccxt::dict{
          {std::string("currency"), code},
          {std::string("cost"), feeCost},
      };
    }
    ccxt::any address = this->safeString(transaction, std::string("address"));
    ccxt::any txid = this->safeString(transaction, std::string("txhash"));
    return ccxt::dict{
        {std::string("info"), transaction},
        {std::string("id"), id},
        {std::string("txid"), txid},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("network"), ccxt::any{}},
        {std::string("addressFrom"), ccxt::any{}},
        {std::string("address"), address},
        {std::string("addressTo"), address},
        {std::string("tagFrom"), ccxt::any{}},
        {std::string("tag"), ccxt::any{}},
        {std::string("tagTo"), ccxt::any{}},
        {std::string("type"), type},
        {std::string("amount"), amount},
        {std::string("currency"), code},
        {std::string("status"), this->parseTransactionState(state)},
        {std::string("updated"), ccxt::any{}},
        {std::string("comment"), ccxt::any{}},
        {std::string("internal"), ccxt::any{}},
        {std::string("fee"), fee},
    };
  }

