  /**
   * @method
   * @name blockchaincom#fetchBalance
   * @description query for balance and get the amount of funds available for
   * trading or funds locked in orders
   * @see https://api.blockchain.com/v3/#getaccounts
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<ccxt::any>
  fetchBalance(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any accountName = this->safeString(
                     params, std::string("account"), std::string("primary"));
                 params = this->omit(params, std::string("account"));
                 ccxt::any request = ccxt::dict{
                     {std::string("account"), accountName},
                 };
                 ccxt::any response = awaitValue(
                     this->privateGetAccounts(this->extend(request, params)));
                 //
                 //     {
                 //         "primary": [
                 //             {
                 //                 "currency":"ETH",
                 //                 "balance":0.009,
                 //                 "available":0.009,
                 //                 "balance_local":30.82869,
                 //                 "available_local":30.82869,
                 //                 "rate":3425.41
                 //             },
                 //             ...
                 //         ]
                 //     }
                 //
                 ccxt::any balances = this->safeValue(response, accountName);
                 if (isTrue(isEqual(balances, ccxt::any{}))) {
                   throw ExchangeError(toString(add(
                       add(add(this->id,
                               std::string(
                                   " fetchBalance() could not find the \"")),
                           accountName),
                       std::string("\" account"))));
                 }
                 ccxt::any result = ccxt::dict{
                     {std::string("info"), response},
                 };
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(balances));
                      postFixIncrement(i)) {
                   ccxt::any entry = ::getValue(balances, i);
                   ccxt::any currencyId =
                       this->safeString(entry, std::string("currency"));
                   ccxt::any code = this->safeCurrencyCode(currencyId);
                   ccxt::any account = this->account();
                   ::setValue(
                       account, std::string("free"),
                       this->safeString(entry, std::string("available")));
                   ::setValue(account, std::string("total"),
                              this->safeString(entry, std::string("balance")));
                   ::setValue(result, code, account);
                 }
                 return this->safeBalance(result);
               })
        .share();
  }

