  ccxt::any sign(ccxt::any path, ccxt::any api = std::string("public"),
                 ccxt::any method = std::string("GET"),
                 ccxt::any params = ccxt::dict{},
                 ccxt::any headers = ccxt::any{},
                 ccxt::any body = ccxt::any{}) override {
    ccxt::any requestPath =
        add(std::string("/"), this->implodeParams(path, params));
    ccxt::any url =
        add(::getValue(::getValue(this->urls, std::string("api")), api),
            requestPath);
    ccxt::any query = this->omit(params, this->extractParams(path));
    if (isTrue(isEqual(api, std::string("public")))) {
      if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
        url = add(url, add(std::string("?"), this->urlencode(query)));
      }
    } else if (isTrue(isEqual(api, std::string("private")))) {
      this->checkRequiredCredentials();
      headers = ccxt::dict{
          {std::string("X-API-Token"), this->secret},
      };
      if (isTrue((isEqual(method, std::string("GET"))))) {
        if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
          url = add(url, add(std::string("?"), this->urlencode(query)));
        }
      } else {
        body = this->json(query);
        ::setValue(headers, std::string("Content-Type"),
                   std::string("application/json"));
      }
    }
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), body},
        {std::string("headers"), headers},
    };
  }

  ccxt::any handleErrors(ccxt::any code, ccxt::any reason, ccxt::any url,
                         ccxt::any method, ccxt::any headers, ccxt::any body,
                         ccxt::any response, ccxt::any requestHeaders,
                         ccxt::any requestBody) override {
    // {"timestamp":"2021-10-21T15:13:58.837+00:00","status":404,"error":"Not
    // Found","message":"","path":"/orders/505050"
    if (isTrue(isEqual(response, ccxt::any{}))) {
      return ccxt::any{};
    }
    ccxt::any text = this->safeString(response, std::string("text"));
    if (isTrue(!isEqual(text, ccxt::any{}))) {
      if (isTrue(isEqual(text, std::string("Insufficient Balance")))) {
        throw InsufficientFunds(
            toString(add(add(this->id, std::string(" ")), body)));
      }
    }
    ccxt::any errorCode = this->safeString(response, std::string("status"));
    ccxt::any errorMessage = this->safeString(response, std::string("error"));
    if (isTrue(!isEqual(code, ccxt::any{}))) {
      ccxt::any feedback =
          add(add(this->id, std::string(" ")), this->json(response));
      this->throwExactlyMatchedException(
          ::getValue(this->exceptions, std::string("exact")), errorCode,
          feedback);
      this->throwBroadlyMatchedException(
          ::getValue(this->exceptions, std::string("broad")), errorMessage,
          feedback);
    }
    return ccxt::any{};
  }
